create table if not exists public.student_support_contacts (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 1 and 160),role text not null default 'Other',organization text not null default '',email text not null default '',phone text not null default '',last_contact date,follow_up_date date,notes text not null default '' check(char_length(notes)<=5000),updated_at timestamptz not null default now());
create index if not exists student_support_contacts_user_followup_idx on public.student_support_contacts(user_id,follow_up_date);
alter table public.student_support_contacts enable row level security;revoke all on public.student_support_contacts from anon;grant select,insert,update,delete on public.student_support_contacts to authenticated;
create policy "Students manage own support contacts" on public.student_support_contacts for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
